const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < input.length && input[offset] <= 32) {
            offset++;
        }
        if (offset >= input.length) return null;
        let res = 0;
        while (offset < input.length && input[offset] > 32) {
            res = res * 10 + (input[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = nextInt();
    if (n === null) return;

    const count = new Int32Array(1001);
    for (let i = 0; i < n; i++) {
        count[nextInt()]++;
    }

    let total = 0;
    let itemsCount = 0;

    for (let p = 1000; p >= 1; p--) {
        while (count[p] > 0) {
            itemsCount++;
            if (itemsCount % 3 !== 0) {
                total += p;
            }
            count[p]--;
        }
    }

    console.log(total);
}

solve();
